// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ChunkText Chunk text into smaller segments
	// (POST /chunk)
	ChunkText(w http.ResponseWriter, r *http.Request)
	// GenerateEmbeddings Generate embeddings
	// (POST /embed)
	GenerateEmbeddings(w http.ResponseWriter, r *http.Request)
	// ExtractJSON Extract entities, relations, classifications, and structures
	// (POST /extract)
	ExtractJSON(w http.ResponseWriter, r *http.Request)
	// GenerateContent Generate text using LLM (OpenAI-compatible)
	// (POST /generate)
	GenerateContent(w http.ResponseWriter, r *http.Request)
	// GenerateBatchContent Generate text for a synchronous batch of requests
	// (POST /generate/batch)
	GenerateBatchContent(w http.ResponseWriter, r *http.Request)
	// ListModels List available models
	// (GET /models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// ReadImages Read text from images (OCR/document understanding)
	// (POST /read)
	ReadImages(w http.ResponseWriter, r *http.Request)
	// RerankPrompts Rerank prompts by relevance
	// (POST /rerank)
	RerankPrompts(w http.ResponseWriter, r *http.Request)
	// RewriteText Rewrite text using Seq2Seq models
	// (POST /rewrite)
	RewriteText(w http.ResponseWriter, r *http.Request)
	// TranscribeAudio Transcribe audio to text (speech-to-text)
	// (POST /transcribe)
	TranscribeAudio(w http.ResponseWriter, r *http.Request)
}

